package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RequirePkceVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property require pkce of trusted client ")
  void test_require_pkce_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> RequirePkceVO.tryFrom(null));
    Assertions.assertEquals(true, RequirePkceVO.from(true).isRequirePkce());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> RequirePkceVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", RequirePkceVO.from(true).toString());
  }
}
